    const orchestrator = createChatOrchestrator(createErrorProvider(original), promptBuilder, undefined, {
      hooks: {
        onError: async (_session, error) => {
          receivedByHook = error;
        },
      },
    });

    const receivedByCaller = await orchestrator
      .processMessage(createSession('hello'))
      .then(() => undefined, error => error);

    expect({hook: receivedByHook === original, caller: receivedByCaller === original}).toEqual({
      hook: true,
      caller: true,
    });
  });
});
